use std::io

fn digit_val(c: int) -> int {
    if c >= 48 && c <= 57 {
        return c - 48
    }
    return c - 65 + 10
}

fn main() {
    let input = io::read_all()
    for line in input.split("\n") {
        let parts = line.trim().split(" ")
        if parts.len() < 3 {
            continue
        }
        let s = parts[0]
        let from = parts[1].parse::<int>().unwrap()
        let to = parts[2].parse::<int>().unwrap()
        let mut n = 0
        for b in s.bytes() {
            n = n * from + digit_val(b as int)
        }
        if n == 0 {
            println("0")
            continue
        }
        let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let mut out = ""
        while n > 0 {
            let d = n % to
            out = digits.substring(d, d + 1) + out
            n = n / to
        }
        println(out)
    }
}
